CREATE TABLE projected_work_author WITH (format='PARQUET',write_compression='ZSTD') AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id,try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS author_id,a.author_position,coalesce(a.is_corresponding,false) AS is_corresponding FROM raw_works w CROSS JOIN UNNEST(w.authorships) AS u(a) WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL;
